<script setup lang="ts">import {ref} from 'vue';import api from '@/api/axios';import {apiErrorMessage} from '@/utils/validation';const format=ref<'xlsx'|'pdf'>('xlsx');const busy=ref(false);const message=ref('');async function download(){busy.value=true;message.value='';try{const r=await api.get('/admin/reports/employees/export',{params:{format:format.value},responseType:'blob'});const u=URL.createObjectURL(r.data);const a=document.createElement('a');a.href=u;a.download=`laporan-sikapj.${format.value}`;a.click();URL.revokeObjectURL(u);message.value='Laporan berhasil diunduh.'}catch(e){message.value=apiErrorMessage(e,'Endpoint ekspor laporan belum tersedia di server.')}finally{busy.value=false}};</script>
<template><section class="space-y-6"><div><h1 class="text-2xl font-bold">Ekspor Laporan</h1><p class="text-sm text-slate-500">Unduh rekap pegawai, kelengkapan berkas, dan jadwal KGB/KP.</p></div><div class="bg-white border rounded-xl p-6 max-w-xl"><label class="block text-sm font-semibold mb-2">Format laporan</label><select v-model="format" class="w-full border rounded-lg p-2"><option value="xlsx">Excel (.xlsx)</option><option value="pdf">PDF (.pdf)</option></select><button @click="download" :disabled="busy" class="mt-4 px-4 py-2 bg-primary-600 text-white rounded-lg disabled:opacity-50">{{busy?'Menyiapkan...':'Unduh Laporan'}}</button><p v-if="message" role="status" class="mt-4 text-sm text-slate-600">{{message}}</p></div></section></template>